package ru.artem.beforethefall.equipment;
import org.bukkit.Bukkit;import org.bukkit.ChatColor;import org.bukkit.Material;import org.bukkit.NamespacedKey;import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.EquipmentSlot;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.scheduler.BukkitTask;import ru.artem.beforethefall.BeforeTheFallPlugin;import java.util.List;
public final class GasMaskManager implements Listener {
 private final BeforeTheFallPlugin plugin;private final NamespacedKey marker,filter,filterItem;private BukkitTask task;
 public GasMaskManager(BeforeTheFallPlugin p){plugin=p;marker=new NamespacedKey(p,"gas_mask");filter=new NamespacedKey(p,"filter_ticks");filterItem=new NamespacedKey(p,"replacement_filter");}
 public ItemStack createMask(){ItemStack i=new ItemStack(Material.CARVED_PUMPKIN);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.DARK_GREEN+"Противогаз");m.setCustomModelData(21);m.setLore(List.of(ChatColor.GRAY+"Защита от радиоактивной пыли и пепла",ChatColor.GRAY+"Сменный фильтр: 15 минут",ChatColor.YELLOW+"Надень в слот шлема"));m.getPersistentDataContainer().set(marker,PersistentDataType.BYTE,(byte)1);m.getPersistentDataContainer().set(filter,PersistentDataType.INTEGER,0);i.setItemMeta(m);return i;}
 public ItemStack createFilter(){ItemStack i=new ItemStack(Material.PAPER);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.GREEN+"Сменный фильтр");m.setCustomModelData(20);m.setLore(List.of(ChatColor.GRAY+"Отдельный картридж противогаза",ChatColor.GRAY+"Ресурс: "+plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900)+" секунд"));m.getPersistentDataContainer().set(filterItem,PersistentDataType.BYTE,(byte)1);i.setItemMeta(m);return i;}
 public boolean isFilter(ItemStack i){if(i==null||!i.hasItemMeta())return false;Byte v=i.getItemMeta().getPersistentDataContainer().get(filterItem,PersistentDataType.BYTE);return v!=null&&v==(byte)1;}
 public boolean isMask(ItemStack i){if(i==null||!i.hasItemMeta())return false;Byte v=i.getItemMeta().getPersistentDataContainer().get(marker,PersistentDataType.BYTE);return v!=null&&v==(byte)1;}
 private int filterTicks(ItemStack i){if(!isMask(i))return 0;Integer v=i.getItemMeta().getPersistentDataContainer().get(filter,PersistentDataType.INTEGER);return v==null?0:v;}
 public int remainingSeconds(ItemStack i){return Math.max(0,filterTicks(i)/2);}
 private void setFilterTicks(ItemStack i,int t){ItemMeta m=i.getItemMeta();m.getPersistentDataContainer().set(filter,PersistentDataType.INTEGER,Math.max(0,t));m.setLore(List.of(ChatColor.GRAY+"Защита от радиоактивной пыли и пепла",ChatColor.GRAY+"Осталось: "+Math.max(0,t/2)+" сек.",t>0?ChatColor.GREEN+"Фильтр установлен":ChatColor.RED+"Фильтр пуст"));i.setItemMeta(m);}
 public boolean isProtected(Player p){ItemStack h=p.getInventory().getHelmet();return isMask(h)&&filterTicks(h)>0;}
 @EventHandler public void onFilterUse(PlayerInteractEvent e){if(e.getHand()!=EquipmentSlot.HAND||!isFilter(e.getItem()))return;ItemStack h=e.getPlayer().getInventory().getHelmet();if(!isMask(h)){e.getPlayer().sendMessage(ChatColor.RED+"Сначала надень противогаз в слот шлема.");e.setCancelled(true);return;}setFilterTicks(h,plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900)*2);ItemStack held=e.getItem();if(held!=null&&held.getAmount()>1)held.setAmount(held.getAmount()-1);else e.getPlayer().getInventory().setItemInMainHand(null);e.getPlayer().sendMessage(ChatColor.GREEN+"Фильтр установлен: 15 минут защиты.");e.setCancelled(true);}
 public void start(){task=Bukkit.getScheduler().runTaskTimer(plugin,()->{for(Player p:Bukkit.getOnlinePlayers()){ItemStack h=p.getInventory().getHelmet();if(!isMask(h))continue;int r=filterTicks(h);if(r<=0)continue;setFilterTicks(h,r-1);if(r==1)p.sendMessage(ChatColor.RED+"Фильтр противогаза исчерпан!");}},10L,10L);}
 public void stop(){if(task!=null)task.cancel();}
}
